// From workflow 01's change_viewing tool. contact_id comes from the
// conversation (not from the model), so only the client's own bookings match.
const i = $input.first().json;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const fail = (error) => [{ json: { ok: false, error } }];
if (!uuid.test(String(i.tenant_id || ''))) return fail('missing agency');
if (!uuid.test(String(i.contact_id || ''))) return fail('the client is not identified yet, so their bookings can\'t be found');
if (!uuid.test(String(i.appointment_id || ''))) return fail('that booking id is not valid; use an appointment_id from UPCOMING VIEWINGS');
if (!['confirm', 'reschedule', 'cancel'].includes(i.action)) return fail('action must be confirm, reschedule or cancel');
return [{ json: { ok: true, tenant_id: i.tenant_id, contact_id: i.contact_id, appointment_id: i.appointment_id, action: i.action,
  new_starts_at: i.new_starts_at || '', new_ends_at: i.new_ends_at || '', reason: String(i.reason || '').slice(0, 300),
  conversation_id: i.conversation_id || '', channel: i.channel || '' } }];

const fmt = (iso, tz, locale) => new Date(iso).toLocaleString(locale, { timeZone: tz || 'Europe/Warsaw', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const rawEmail = (to, subject, body) => Buffer.from(
  [`To: ${to}`, `Subject: =?UTF-8?B?${b64(subject)}?=`, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64'].join('\r\n') +
  '\r\n\r\n' + b64(body)).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// One row when the booking is this client's, nothing otherwise.
const r = $input.first().json || {};
const v = $('Validate Change').first().json;
const fail = (error) => [{ json: { ok: false, action: v.action, error } }];
if (!r.appointment_id) return fail('no booking with that id for this client');
if (r.status !== 'confirmed') return fail(`that booking is already ${String(r.status).replace('_', ' ')}`);
if (new Date(r.starts_at) < new Date()) return fail('that booking is in the past');
const out = { ok: true, ...v, info: r, when: fmt(r.starts_at, r.timezone, 'en-GB'),
  has_event: !!(r.google_calendar_id && r.external_calendar_id) };
if (v.action === 'reschedule') {
  const s = new Date(v.new_starts_at), e = new Date(v.new_ends_at);
  if (isNaN(s) || isNaN(e) || e <= s) return fail('the new time is missing or not valid; call check_availability and use one of its slots');
  const notice = Number(r.booking_notice_minutes) || 0;
  if (s < new Date(Date.now() + notice * 60000)) return fail(`the new time is too soon (bookings need ${notice} minutes' notice)`);
  out.new_when = fmt(v.new_starts_at, r.timezone, 'en-GB');
}
return [{ json: out }];

const fmt = (iso, tz, locale) => new Date(iso).toLocaleString(locale, { timeZone: tz || 'Europe/Warsaw', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const rawEmail = (to, subject, body) => Buffer.from(
  [`To: ${to}`, `Subject: =?UTF-8?B?${b64(subject)}?=`, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64'].join('\r\n') +
  '\r\n\r\n' + b64(body)).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// After a cancel or a move: tell the agent (or the agency's alert address) and
// email the client. Demo agency: client only, marked DEMO.
const c = $('Check Booking').first().json;
const i = c.info;
const tz = i.timezone;
const isCall = i.assistant_mode === 'sales';
const isDemo = i.assistant_mode === 'demo';
const noun = isCall ? 'call' : 'viewing';
let calendar = 'no_event';
if (c.action === 'reschedule' && c.has_event) {
  try {
    const p = $('Move Calendar Event').first().json;
    const st = Number(p.statusCode || 0);
    calendar = st >= 200 && st < 300 ? 'updated' : 'failed';
  } catch (e) { calendar = 'failed'; }
}
if (c.action === 'cancel' && c.has_event) {
  try {
    const d = $('Delete Calendar Event').first().json;
    const st = Number(d.statusCode || 0);
    calendar = (st >= 200 && st < 300) || st === 404 || st === 410 ? 'deleted' : 'failed';
  } catch (e) { calendar = 'failed'; }
}
const first = String(i.contact_name || '').trim().split(/\s+/)[0] || '';
const place = [i.listing_title, i.listing_address].filter(Boolean).join(', ');
const via = { whatsapp: 'WhatsApp', email: 'email', chat_widget: 'the website chat' }[c.channel] || 'chat';
const convo = c.conversation_id ? `\nConversation: https://app.getelliot.eu/dashboard/conversations/${c.conversation_id}` : '';
const emails = [];
const team = isDemo ? null : (i.agent_email || i.notify_email);
const newWhenPl = c.new_starts_at ? fmt(c.new_starts_at, tz, 'pl-PL') : '';
const whenPl = fmt(i.starts_at, tz, 'pl-PL');

if (c.action === 'cancel') {
  if (team) emails.push({ to: team, kind: 'team',
    subject: `Cancelled by the client: ${i.contact_name || 'client'}, ${c.when}`,
    body: `${i.contact_name || 'The client'} cancelled their ${noun} on ${c.when}${place ? ` (${place})` : ''} via ${via}.` +
      (c.reason ? `\nReason: ${c.reason}` : '') + `\nThe calendar entry was ${calendar === 'failed' ? 'NOT removed, please delete it by hand' : 'removed'}.` + convo + '\n' });
  if (i.contact_email) emails.push({ to: i.contact_email, kind: 'client',
    subject: `${isDemo ? '[DEMO] ' : ''}Cancelled: your ${noun} on ${c.when}`,
    body: `Hi${first ? ' ' + first : ''},\n\n${isDemo ? 'This is a DEMO from getelliot.eu.\n\n' : ''}your ${noun} on ${c.when}${place ? ` (${place})` : ''} is cancelled, as you asked. ` +
      `If you'd like another time, just reply.\n\n${i.tenant_name}\n\n----------------------------------------\n\n` +
      `Dzień dobry${first ? ' ' + first : ''},\n\n${isDemo ? 'To jest DEMO z getelliot.eu.\n\n' : ''}zgodnie z prośbą odwołaliśmy termin ${whenPl}${place ? ` (${place})` : ''}. ` +
      `Jeśli chcą Państwo umówić inny, wystarczy odpowiedzieć.\n\n${i.tenant_name}\n` });
} else {
  if (team) emails.push({ to: team, kind: 'team',
    subject: `Moved by the client: ${i.contact_name || 'client'}, now ${c.new_when}`,
    body: `${i.contact_name || 'The client'} moved their ${noun}${place ? ` (${place})` : ''} via ${via}:\nwas ${c.when}\nnow ${c.new_when}` +
      (c.reason ? `\nReason: ${c.reason}` : '') +
      `\nThe calendar entry was ${calendar === 'failed' ? 'NOT updated, please move it by hand' : calendar === 'updated' ? 'updated' : 'not there (no calendar event)'}.` + convo + '\n' });
  if (i.contact_email) emails.push({ to: i.contact_email, kind: 'client',
    subject: `${isDemo ? '[DEMO] ' : ''}New time: your ${noun} on ${c.new_when}`,
    body: `Hi${first ? ' ' + first : ''},\n\n${isDemo ? 'This is a DEMO from getelliot.eu.\n\n' : ''}your ${noun}${place ? ` (${place})` : ''} has moved to ${c.new_when}.` +
      `${/Google Meet: (\S+)/.test(i.notes || '') ? `\nGoogle Meet: ${(i.notes.match(/Google Meet: (\S+)/) || [])[1]}` : ''}\n\nNeed another change? Just reply.\n\n${i.tenant_name}\n\n----------------------------------------\n\n` +
      `Dzień dobry${first ? ' ' + first : ''},\n\n${isDemo ? 'To jest DEMO z getelliot.eu.\n\n' : ''}nowy termin${place ? ` (${place})` : ''}: ${newWhenPl}.\n\nJeśli trzeba coś zmienić, wystarczy odpowiedzieć.\n\n${i.tenant_name}\n` });
}
return emails.length
  ? emails.map((e) => ({ json: { ...e, calendar, raw_message: rawEmail(e.to, e.subject, e.body) } }))
  : [{ json: { to: null, calendar } }];

// Back to workflow 01's Build Tool Result Message.
const safe = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const safeAll = (n) => { try { return $(n).all().map((x) => x.json); } catch (e) { return []; } };
const v = safe('Validate Change') || {};
const c = safe('Check Booking');
if (!v.ok) return [{ json: { success: false, action: v.action, error: v.error } }];
if (!c || !c.ok) return [{ json: { success: false, action: v.action, error: (c && c.error) || 'not found' } }];
if (c.action === 'confirm') {
  const done = safe('Mark Confirmed');
  return [{ json: done && done.done ? { success: true, action: 'confirm', when: c.when } : { success: false, action: 'confirm', error: 'the booking changed meanwhile' } }];
}
if (c.action === 'reschedule') {
  const m = (safe('Move In Dashboard') || {}).result || {};
  if (!m.ok) {
    const why = { slot_unavailable: 'that time was just taken; offer other times', in_the_past: 'that time is in the past', not_found: 'the booking changed meanwhile' };
    return [{ json: { success: false, action: 'reschedule', error: why[m.error] || m.error || 'could not move it' } }];
  }
}
if (c.action === 'cancel' && !(safe('Mark Cancelled') || {}).done) {
  return [{ json: { success: false, action: 'cancel', error: 'the booking changed meanwhile' } }];
}
const built = safeAll('Build Emails');
const sent = safeAll('Send Email');
const clientIdx = built.findIndex((e) => e.kind === 'client');
const clientSent = clientIdx >= 0 && sent[clientIdx] && Number(sent[clientIdx].statusCode) >= 200 && Number(sent[clientIdx].statusCode) < 300;
return [{ json: { success: true, action: c.action, when: c.action === 'reschedule' ? c.new_when : c.when, previous_when: c.when,
  calendar: (built[0] || {}).calendar || 'no_event', email_sent_to: clientSent ? built[clientIdx].to : null } }];
